{
  "name": "opencode-free-fleet",
  "version": "0.4.0",
  "description": "Economic Load Balancing and Zero-Cost Model Discovery for OpenCode - v0.3.0 Release",
  "author": {
    "name": "Phorde",
    "email": "phorde@hotmail.com"
  },
  "type": "module",
  "main": "./dist/index.js",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./opencode": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/phorde/opencode-free-fleet"
  },
  "publishConfig": {
    "access": "public"
  },
  "files": [
    "dist",
    "src/version.ts"
  ],
  "dependencies": {
    "@opencode-ai/plugin": "^1.1.0"
  },
  "devDependencies": {
    "@eslint/js": "^9.39.1",
    "@types/node": "^20.11.5",
    "@typescript-eslint/eslint-plugin": "8.47.0",
    "@typescript-eslint/parser": "8.47.0",
    "bun-types": "latest",
    "eslint": "^9.39.1",
    "eslint-config-prettier": "10.1.8",
    "eslint-plugin-prettier": "^5.1.3",
    "prettier": "^3.2.4",
    "typescript-eslint": "^8.47.0",
    "vitest": "^3.2.4"
  },
  "scripts": {
    "build": "bun run build:tsc",
    "build:tsc": "bun scripts/build.ts",
    "test": "bun test",
    "publish": "bun publish --access public",
    "prepublishOnly": "bun run build"
  },
  "keywords": [
    "opencode",
    "llm",
    "free-models",
    "model-discovery",
    "economic-load-balancing",
    "zero-cost",
    "benchmark-performance",
    "sota",
    "multi-provider",
    "metadata-oracle",
    "75+ providers",
    "zero-config",
    "live-updates",
    "ultra-free-mode",
    "v0.3.0"
  ]
}
